export { Zoom } from "./Options/Classes/Zoom.js";
export { initialTouchDistance, maxZoom, minZoom, touchCenterDivisor, touchPointIndexFirst, touchPointIndexSecond, touchPointsCount, zoomGestureFactor, zoomInFactor, zoomOutFactor, } from "./Utils/Constants.js";
export async function loadZoomPlugin(engine) {
    engine.checkVersion("4.3.2");
    await engine.pluginManager.register(async (e) => {
        const { ZoomPlugin } = await import("./ZoomPlugin.js");
        e.pluginManager.addPlugin(new ZoomPlugin());
    });
}
